package com.msp1974.vacompanion.nearest

import java.io.File
import kotlin.math.abs

/** Dependency-free JVM regression suite. Fixtures are independently generated by Go's crypto/DSP oracle. */
object NearestCoreTests {
    private val epoch = 1_793_293_200_000L
    private val nonce = ByteArray(12) { it.toByte() }

    @JvmStatic fun main(args: Array<String>) {
        val fixtures = File(args.firstOrNull() ?: "integrations/vaca-nearest/src/test/golden-vectors.txt")
            .readLines().associate { it.substringBefore('=') to it.substringAfter('=') }
        val cases = execute(fixtures, null)
        println("${cases.size} nearest core tests passed")
    }

    /** Used by JUnit without adding JUnit dependencies to the standalone compiler path. */
    fun caseNames(fixtures: Map<String, String>): List<String> = execute(fixtures, emptySet())

    fun runCase(name: String, fixtures: Map<String, String>) { execute(fixtures, setOf(name)) }

    private fun execute(fixtures: Map<String, String>, selected: Set<String>?): List<String> {
        val cases = mutableListOf<String>()
        fun test(name: String, body: () -> Unit) {
            check(name !in cases) { "Duplicate test case: $name" }
            cases.add(name)
            if (selected == null || name in selected) {
                try { body() } catch (e: Throwable) { throw AssertionError(name, e) }
            }
        }
        for ((label, word, recipient) in listOf(
            Triple("ascii", "offline-example-house-word", "Echo-Kitchen"),
            Triple("unicode", "Пример слова дома 🔑 offline", "İSTANBUL-Σ"),
        )) {
            val body = fixtures.getValue("$label.body").unhex()!!
            var mono = 1000L
            val auth = NearestAuthenticator(word, epoch - 20_000) { mono }
            val header = fixtures.getValue("$label.header")
            test("$label Go request signature") { check(auth.signWithNonce(body, recipient, epoch, nonce) == header) }
            test("$label Go answered proof") {
                check(auth.answeredProof(header, "show-office", recipient) == fixtures.getValue("$label.proof"))
                check(auth.verifyAnswered(fixtures.getValue("$label.proof"), header, "SHOW-OFFICE", recipient))
            }
            test("$label raw-body/target authentication before nonce consumption") {
                check(!auth.verify(header, body + 32.toByte(), recipient, epoch))
                check(!auth.verify(header, body, "wrong-device", epoch))
                check(auth.verify(header, body, recipient, epoch))
                check(!auth.verify(header, body, recipient, epoch))
            }
            test("$label unsigned/rebound409 rejection") {
                val proof = fixtures.getValue("$label.proof")
                check(!auth.verifyAnswered(null, header, "show-office", recipient))
                check(!auth.verifyAnswered(proof, header, "another-show", recipient))
                val next = auth.signWithNonce(body, recipient, epoch, ByteArray(12) { 7 })
                check(!auth.verifyAnswered(proof, next, "show-office", recipient))
            }
            test("$label body decode and encode") {
                val claim = NearestWire.decodeClaim(body)!!
                check(claim.from == "show-office" && claim.score == 25.5)
                check(NearestWire.decodeClaim(NearestWire.encodeClaim(claim)) == claim)
            }
            auth.close()
            test("$label closed keys reject verification") { check(!auth.verify(header, body, recipient, epoch)) }
        }

        val body = fixtures.getValue("ascii.body").unhex()!!
        var clock = 0L
        val auth = NearestAuthenticator("offline-example-house-word", epoch) { clock }
        fun signedAt(at: Long, id: Int = 1): String = auth.signWithNonce(body, "receiver", at,
            ByteArray(12).also { it[8] = (id ushr 24).toByte(); it[9] = (id ushr 16).toByte(); it[10] = (id ushr 8).toByte(); it[11] = id.toByte() })
        test("freshness exact bounds and startup floor") {
            check(!auth.looksSigned(signedAt(epoch - 1000), epoch))
            clock = 10_000
            check(auth.looksSigned(signedAt(epoch + 5000), epoch + 10_000))
            check(auth.looksSigned(signedAt(epoch + 15_000), epoch + 10_000))
            check(!auth.looksSigned(signedAt(epoch + 4000), epoch + 10_000))
            check(!auth.looksSigned(signedAt(epoch + 16_000), epoch + 10_000))
            check(!auth.looksSigned("v1 1793293200 00 " + "0".repeat(64), epoch))
            check(!auth.looksSigned("v2 9223372036854775807 " + "0".repeat(24) + " " + "0".repeat(64), epoch))
        }
        test("backward wall clock does not reject every new claim") {
            clock = 60_000
            check(auth.looksSigned(signedAt(epoch - 30_000), epoch - 30_000))
        }
        test("replay cache bounded and expires only outside replay horizon") {
            clock = 100_000
            for (i in 0 until 1024) check(auth.verify(signedAt(epoch + 100_000, i), body, "receiver", epoch + 100_000))
            check(!auth.verify(signedAt(epoch + 100_000, 1024), body, "receiver", epoch + 100_000))
            clock += 11_000
            check(auth.verify(signedAt(epoch + 111_000, 1024), body, "receiver", epoch + 111_000))
        }
        auth.close()

        test("JSON bounded and strict without depending on map order") {
            check(NearestWire.decodeClaim(ByteArray(4097)) == null)
            check(NearestWire.decodeClaim("{\"from\":\"x\",\"from\":\"y\",\"score\":1}".toByteArray()) == null)
            check(NearestWire.decodeClaim("{\"from\":\"x\",\"score\":1e999}".toByteArray()) == null)
            check(NearestWire.decodeClaim("{\"from\":\"x\",\"score\":01}".toByteArray()) == null)
            check(NearestWire.decodeClaim(byteArrayOf(-1)) == null)
            val claim = NearestClaim("café\n\"\\", "test", "Привет, Мышка", 1.0)
            check(NearestWire.decodeClaim(NearestWire.encodeClaim(claim)) == claim)
            check(NearestWire.decodeClaim("{\"from\":\"x\",\"extra\":[{\"v\":true}],\"score\":1}".toByteArray())!!.score == 1.0)
        }

        fun c(name: String, score: Double, word: String = "same") = NearestClaim(name, "turn", word, score)
        test("higher score wins independent of packet ordering") {
            for (reverse in listOf(false, true)) {
                val e = NearestElection(); val p = e.begin(c("show", 20.0), 1000)
                val claims = listOf(c("dot-a", 10.0), c("dot-b", 21.0))
                (if (reverse) claims.reversed() else claims).forEach { e.receive(it, 1100) }
                check(e.decide(p, 1299) == NearestElection.Decision.WAIT)
                check(e.decide(p, 1300) == NearestElection.Decision.YIELD)
                check(e.decide(p, 1301) == NearestElection.Decision.STALE)
            }
        }
        test("tie follows Go UTF8 ordering including supplementary code points") {
            check(NearestElection.better(c("A", 1.0), c("a", 1.0)))
            check(NearestElection.better(c("\uE000", 1.0), c("\uD800\uDC00", 1.0)))
        }
        test("unrelated word and old claim do not suppress local wake") {
            val e = NearestElection(); e.receive(c("a", 90.0), 699)
            e.receive(c("b", 90.0, "different"), 1100)
            val p = e.begin(c("show", 20.0), 1000)
            check(e.decide(p, 1300) == NearestElection.Decision.START)
        }
        test("claim at exact early window boundary participates") {
            val e = NearestElection(); e.receive(c("a", 21.0), 700)
            val p = e.begin(c("show", 20.0), 1000)
            check(e.decide(p, 1300) == NearestElection.Decision.YIELD)
        }
        test("signed already-answered preempts even a better local score") {
            val e = NearestElection(); val p = e.begin(c("show", 90.0), 1000)
            e.markAnsweredElsewhere(p)
            check(e.decide(p, 1300) == NearestElection.Decision.YIELD)
        }
        test("winner retains turn for twice its own window and never indefinitely") {
            val e = NearestElection(); val p = e.begin(c("show", 20.0), 1000)
            check(e.decide(p, 1300) == NearestElection.Decision.START)
            check(e.receive(c("a", 90.0), 1600))
            check(!e.receive(c("a", 90.0), 1601))
            check(!e.receive(c("a", 90.0, "other"), 1400))
        }
        test("cannot-answer path does not claim an answered lease") {
            val e = NearestElection(); val p = e.begin(c("show", 20.0), 1000)
            check(e.decide(p, 1300, false) == NearestElection.Decision.START)
            check(!e.receive(c("a", 90.0), 1400))
        }
        test("cancelled and replaced timers are inert") {
            val e = NearestElection(); val p = e.begin(c("show", 20.0), 1000)
            e.cancel(); check(e.decide(p, 1300) == NearestElection.Decision.STALE)
            val old = e.begin(c("show", 20.0), 2000); val next = e.begin(c("show", 21.0), 2100)
            e.markAnsweredElsewhere(old)
            check(e.decide(old, 2400) == NearestElection.Decision.STALE)
            check(e.decide(next, 2400) == NearestElection.Decision.START)
        }
        test("offsets and call preference stay bounded") {
            check(NearestElection.adjustedScore(40.0, 99.0, true) == 76.0)
            check(NearestElection.adjustedScore(0.0, -99.0, false) == -30.0)
        }

        // Four actual core instances, but simulated clocks/transports. No real devices or traffic.
        fun fourPeer(starts: List<Long>, scores: List<Double>, partition: Boolean = false): String {
            data class Event(val at: Long, val kind: Int, val to: Int, val from: Int)
            val names = listOf("dot-a", "dot-b", "show-a", "show-b")
            val cores = List(4) { NearestElection() }
            val claims = List(4) { c(names[it], scores[it]) }
            val pending = arrayOfNulls<NearestElection.Pending>(4)
            val outcomes = Array(4) { "" }
            val events = mutableListOf<Event>()
            for (i in 0..3) {
                events.add(Event(starts[i], 0, i, i)); events.add(Event(starts[i] + 300, 3, i, i))
                if (!partition) for (j in 0..3) if (i != j) events.add(Event(starts[i] + 20, 1, j, i))
            }
            while (events.isNotEmpty()) {
                events.sortWith(compareBy<Event> { it.at }.thenBy { it.kind })
                val e = events.removeAt(0)
                when (e.kind) {
                    0 -> pending[e.to] = cores[e.to].begin(claims[e.to], e.at)
                    1 -> if (cores[e.to].receive(claims[e.from], e.at)) events.add(Event(e.at + 20, 2, e.from, e.to))
                    2 -> pending[e.to]?.let { cores[e.to].markAnsweredElsewhere(it) }
                    3 -> outcomes[e.to] = cores[e.to].decide(pending[e.to]!!, e.at).name
                }
            }
            return outcomes.joinToString(",")
        }
        for (winner in 0..3) test("four peers: ${listOf("Dot A", "Dot B", "Show A", "Show B")[winner]} wins by score") {
            val scores = MutableList(4) { 30.0 }.also { it[winner] = 60.0 }
            val result = fourPeer(List(4) { 1000L }, scores)
            check(result == fixtures.getValue("four.winner$winner"))
            check(result.split(',').count { it == "START" } == 1)
        }
        test("four peers: deterministic equal score tie matches native Go") {
            check(fourPeer(List(4) { 1000L }, List(4) { 40.0 }) == fixtures.getValue("four.tie"))
        }
        test("four peers: staggered detections still choose best hearing") {
            check(fourPeer(listOf(1000L, 1040L, 1100L, 1150L), listOf(20.0, 50.0, 30.0, 25.0)) == fixtures.getValue("four.delayed"))
        }
        test("four peers: authenticated already-answering proof preserves first winner") {
            check(fourPeer(listOf(1000L, 1420L, 1440L, 1460L), listOf(10.0, 90.0, 80.0, 70.0)) == fixtures.getValue("four.already"))
        }
        test("four peers: partition explicitly fails open, not exactly once") {
            val result = fourPeer(List(4) { 1000L }, listOf(10.0, 90.0, 80.0, 70.0), true)
            check(result == fixtures.getValue("four.partition"))
            check(result == "START,START,START,START")
        }

        val pcm = ShortArray(80_000)
        var state = 1L
        for (n in pcm.indices) {
            state = (state * 1664525 + 1013904223) and 0xffffffffL
            var sample = ((state ushr 24) % 41).toInt() - 20
            if (n in 32_000 until 40_000) sample += if (n % 32 < 16) 4000 else -4000
            pcm[n] = sample.toShort()
        }
        test("DSP matches Go golden timeline including quiet, speech and expiry") {
            val expected = fixtures.getValue("score.timeline").split(',').map(String::toDouble)
            val meter = StandoutScore()
            expected.forEachIndexed { i, value ->
                meter.add(pcm, i * 1600, 1600)
                check(abs(meter.score() - value) < 0.00002) { "block=$i expected=$value actual=${meter.score()}" }
            }
            check(meter.score() == 0.0)
        }
        test("fragmenting audio does not change score or frame cadence") {
            val a = StandoutScore(); val b = StandoutScore(); a.add(pcm, 0, 40000)
            var offset = 0
            while (offset < 40000) { val n = minOf(73, 40000 - offset); b.add(pcm, offset, n); offset += n }
            check(a.score() == b.score())
            b.reset(); check(b.score() == 0.0)
            b.add(ShortArray(16000)); check(b.score() == 0.0)
        }
        test("analog-gain floor reference") {
            check(StandoutScore.dotFloorForAnalogGain(20) == 16f)
            check(StandoutScore.dotFloorForAnalogGain(-20) == 2f)
        }
        require(selected == null || cases.containsAll(selected)) { "Unknown core test case" }
        return cases
    }
}
